# Drives a PWM output on Raspberry Pi GPIO pins using gpiozero
# Reports the state applied to standard output

import time
from gpiozero import PWMOutputDevice

# Define the GPIO pins connected to the PWM outputs
PWM_OUTPUT_PINS = [9, 10, 11, 12, 13]

def initialize_pwm_devices(pin_numbers):
    """Initializes PWMOutputDevices for each specified pin."""
    pwm_devices = []
    for pin_number in pin_numbers:
        try:
            pwm_device = PWMOutputDevice(pin_number, active_high=True, initial_value=0.0)
            pwm_devices.append(pwm_device)
            print(f"PWM output on pin {pin_number} initialized.")
        except Exception as e:
            print(f"Error initializing PWM on pin {pin_number}: {e}")
            return None
    return pwm_devices

def set_pwm_values(pwm_devices, values):
    """Sets the PWM duty cycle for each PWMOutputDevice."""
    if len(pwm_devices) != len(values):
        print("Number of PWM devices and values must match.")
        return False
    for pwm_device, value in zip(pwm_devices, values):
        try:
            pwm_device.value = value
            print(f"PWM value set to {value} on pin {pwm_device.pin}")
        except Exception as e:
            print(f"Error setting PWM value on pin {pwm_device.pin}: {e}")
            return False
    return True

def main():
    """Main function to demonstrate PWM output."""
    pwm_devices = initialize_pwm_devices(PWM_OUTPUT_PINS)
    if pwm_devices is None:
        print("Failed to initialize PWM devices. Exiting.")
        return

    try:
        # Set PWM values for a short test cycle
        pwm_values = [0.2, 0.5, 0.8, 1.0, 0.8]
        if set_pwm_values(pwm_devices, pwm_values):
            print("PWM values set successfully.")
            time.sleep(1)  # Keep the PWM output on for a short period
        else:
            print("Failed to set PWM values.")
    except KeyboardInterrupt:
        print("\nScript interrupted by user.")
    finally:
        # Release the PWM devices and clean up GPIO
        for pwm_device in pwm_devices:
            pwm_device.close()
        print("PWM output demo finished.")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3

"""
This script controls a PCA9685 PWM servo motor using gpiozero on a Raspberry Pi.
It reads a value from stdin, applies it to the motor, and reports the result.
The script is designed for a robotics project, where precise control of servo
motors is essential.
"""

import time
import sys
from gpiozero import PWMOutputDevice

# Configuration
SERVO_CHANNEL = 0
PWM_FREQUENCY = 60
READ_INTERVAL_SECONDS = 0.05

def initialize_servo(channel, frequency):
    """Initializes the PWMOutputDevice for the servo motor."""
    try:
        return PWMOutputDevice(channel, frequency=frequency)
    except Exception as e:
        print(f"Error initializing servo: {e}")
        sys.exit(1)

def read_servo_value():
    """Reads a value from stdin and handles potential errors."""
    try:
        value_str = input("Enter servo value (0-180, or Ctrl+C to exit): ")
        value = float(value_str)
        if not 0.0 <= value <= 180.0:
            raise ValueError("Servo value must be between 0 and 180 degrees.")
        return value
    except ValueError as e:
        print(f"Invalid input: {e}")
        return None
    except EOFError:
        print("\nExiting program.")
        sys.exit(0)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

def apply_servo_command(servo, value):
    """Applies the servo command to the motor and returns the result."""
    try:
        servo.value = value
        return servo.value
    except Exception as e:
        print(f"Error applying servo command: {e}")
        return None

def report_servo_state(servo_value):
    """Prints the current servo state to stdout."""
    print(f"Servo value set to: {servo_value:.2f} degrees")

def main():
    """Main function to control the servo motor."""
    servo = initialize_servo(SERVO_CHANNEL, PWM_FREQUENCY)

    try:
        while True:
            servo_value = read_servo_value()
            if servo_value is not None:
                applied_value = apply_servo_command(servo, servo_value)
                if applied_value is not None:
                    report_servo_state(applied_value)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        # Ensure the servo is stopped and the GPIO resources are released
        servo.close()
        print("Servo motor stopped and GPIO resources released.")

if __name__ == "__main__":
    main()

