#!/usr/bin/env python3

import time
import os
from picamera2 import Picamera2

# Configuration
IMAGE_FILENAME = "image.jpg"
CAPTURE_INTERVAL = 0.01  # seconds
MAX_RETRIES = 3
RETRY_DELAY = 0.1  # seconds

def initialize_camera():
    """Initializes the Raspberry Pi camera module."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration())
        camera.start()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera, filename):
    """Captures an image from the camera and saves it to a file."""
    retries = 0
    while retries < MAX_RETRIES:
        try:
            camera.capture_file(filename)
            print(f"Image captured and saved to {filename}")
            return True
        except Exception as e:
            print(f"Error capturing image (attempt {retries + 1}): {e}")
            retries += 1
            time.sleep(RETRY_DELAY)
    print("Failed to capture image after multiple retries.")
    return False

def main():
    """Main function to capture and save an image."""
    camera = initialize_camera()
    if camera is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        while True:
            if capture_image(camera, IMAGE_FILENAME):
                time.sleep(CAPTURE_INTERVAL)
            else:
                print("Failed to capture image. Retrying in next cycle.")
                time.sleep(CAPTURE_INTERVAL)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        # Ensure camera resources are released
        if camera:
            camera.stop()
            camera.close()
        print("Camera resources released.")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3

"""
This script controls a PCA9685 PWM servo motor using gpiozero on a Raspberry Pi.
It reads a value from stdin, applies it to the motor, and reports the result.
The script is designed for a robotics project, where precise control of a servo
is essential.
"""

import time
import sys
from gpiozero import PWMOutputDevice

# Configuration constants
SERVO_PIN = 2
LED_PIN = 3
PWM_FREQUENCY = 60

def initialize_servo(pin):
    """Initializes the PWMOutputDevice for the servo motor."""
    try:
        return PWMOutputDevice(pin, frequency=PWM_FREQUENCY)
    except Exception as e:
        print(f"Error initializing servo: {e}")
        sys.exit(1)

def read_servo_value():
    """Reads a value from stdin and validates it."""
    try:
        value_str = input("Enter servo value (0-180, or Ctrl+D to quit): ")
        value = float(value_str)
        if 0 <= value <= 180:
            return value
        else:
            print("Invalid value. Please enter a value between 0 and 180.")
            return None
    except ValueError:
        print("Invalid input. Please enter a number.")
        return None
    except EOFError:
        print("\nExiting program.")
        sys.exit(0)

def apply_servo_command(servo, value):
    """Applies the servo command to the motor and reports the result."""
    try:
        servo.value = value
        print(f"Servo value set to: {value}")
    except Exception as e:
        print(f"Error applying servo command: {e}")

def main():
    """Main function to control the servo motor."""
    servo = initialize_servo(SERVO_PIN)

    try:
        while True:
            servo_value = read_servo_value()
            if servo_value is not None:
                apply_servo_command(servo, servo_value)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        servo.close()
        print("Servo motor cleaned up.")

if __name__ == "__main__":
    main()

