#!/usr/bin/env python3

import time
import os
from picamera2 import Picamera2

# Configuration
IMAGE_FILENAME = "image.jpg"
CAPTURE_INTERVAL_SECONDS = 0.5
MAX_CAPTURE_ATTEMPTS = 3

def initialize_camera():
    """Initializes the Raspberry Pi camera module."""
    try:
        camera_device = Picamera2()
        camera_device.configure(camera_device.create_preview_configuration())
        camera_device.start()
        return camera_device
    except Exception as camera_error:
        print(f"Error initializing camera: {camera_error}")
        return None

def capture_image(camera_device, filename):
    """Captures an image from the camera and saves it to the specified file."""
    for attempt in range(MAX_CAPTURE_ATTEMPTS):
        try:
            camera_device.capture_file(filename)
            print(f"Image captured successfully: {filename}")
            return True
        except Exception as capture_error:
            print(f"Error capturing image (attempt {attempt + 1}): {capture_error}")
            time.sleep(0.1)  # Small delay before retrying
    print("Failed to capture image after multiple attempts.")
    return False

def main():
    """Main function to capture and save images."""
    camera_device = initialize_camera()

    if camera_device is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        while True:
            if capture_image(camera_device, IMAGE_FILENAME):
                time.sleep(CAPTURE_INTERVAL_SECONDS)
            else:
                time.sleep(CAPTURE_INTERVAL_SECONDS * 2)  # Wait longer on failure
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        # Ensure camera resources are released
        if camera_device:
            camera_device.close()
            print("Camera resources released.")

if __name__ == "__main__":
    main()

