#!/usr/bin/env python3

"""
Control a 4-channel 5V PWM motor driver via gpiozero on a Raspberry Pi.

This script drives a 4-channel PWM motor driver connected to a Raspberry Pi
using the gpiozero library. It configures each motor pin as PWM output,
sets the PWM frequency to 1000 Hz, and controls the motor speeds based on
user input via stdin.

Hardware Setup:
- Connect the driver's IN1, IN2, IN3, IN4, ENA, ENB, ENA1, ENA2, ENA3, ENA4
  pins to GPIO 5, 6, 13, 17, 18, 22, 23, 24, 27 (BCM numbering) through a
  10k Ohm resistor.
- Connect the driver's VCC, GND, and PWM enable pins to 5V, GND, and GPIO 10
  (BCM numbering) through a 10k Ohm resistor.

Usage:
1. Run the script with root privileges: sudo python3 motor_control.py
2. Enter motor speed values (0-100) for each motor (1-4). Use the
   'q' character to quit.
"""

import time
import sys
from gpiozero import PWMOutputDevice, DigitalOutputDevice

# Define GPIO pins for the motor driver
MOTOR_PINS = {
    1: {'in1': 5, 'in2': 6, 'ena': 10},  # Motor 1
    2: {'in1': 13, 'in2': 17, 'ena': 11},  # Motor 2
    3: {'in1': 18, 'in2': 22, 'ena': 12},  # Motor 3
    4: {'in1': 23, 'in2': 24, 'ena': 13},  # Motor 4
}

# PWM frequency in Hz
PWM_FREQUENCY = 1000

# Initialize PWM outputs for each motor
motors = {}
for motor_num, pins in MOTOR_PINS.items():
    try:
        in1 = DigitalOutputDevice(pins['in1'], active_high=True, initial_value=False)
        in2 = DigitalOutputDevice(pins['in2'], active_high=True, initial_value=False)
        ena = PWMOutputDevice(pins['ena'], frequency=PWM_FREQUENCY)
        motors[motor_num] = {'in1': in1, 'in2': in2, 'ena': ena}
    except Exception as e:
        print(f"Error initializing motor {motor_num}: {e}")
        sys.exit(1)


def set_motor_speed(motor_num, speed):
    """Sets the speed of a specific motor.

    Args:
        motor_num (int): The motor number (1-4).
        speed (float): The desired speed (0-100).
    """
    if not 1 <= motor_num <= 4:
        print("Invalid motor number. Must be between 1 and 4.")
        return

    if not 0 <= speed <= 100:
        print("Invalid speed. Must be between 0 and 100.")
        return

    try:
        if speed == 0:
            motors[motor_num]['in1'].off()
            motors[motor_num]['in2'].off()
            motors[motor_num]['ena'].value = 0
        else:
            if speed > 0:
                motors[motor_num]['in1'].on()
                motors[motor_num]['in2'].off()
            else:
                motors[motor_num]['in1'].off()
                motors[motor_num]['in2'].on()

            motors[motor_num]['ena'].value = abs(speed) / 100  # Convert speed to duty cycle

    except Exception as e:
        print(f"Error setting motor {motor_num} speed: {e}")


def main():
    """Main function to control the motor driver."""
    try:
        while True:
            try:
                motor_input = input("Enter motor speed (1-4) or 'q' to quit: ")
                if motor_input.lower() == 'q':
                    break

                motor_num = int(motor_input)
                speed = float(input("Enter speed (0-100): "))
                set_motor_speed(motor_num, speed)

            except ValueError:
                print("Invalid input. Please enter a number between 1 and 4 or 'q'.")
            except EOFError:
                print("\nExiting program due to EOF.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        # Clean up GPIO pins on exit
        for motor_num, pins in MOTOR_PINS.items():
            try:
                motors[motor_num]['in1'].close()
                motors[motor_num]['in2'].close()
                motors[motor_num]['ena'].close()
            except Exception as e:
                print(f"Error closing motor {motor_num} pins: {e}")
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()
